import json,glob,os
from pathlib import Path
root=Path.home()/"Library/Application Support/youchu-agent-bus/state"
ids={12452,12453,12455}
found={}
for p in root.rglob("*.json*"):
  try:
    raw=p.read_text(encoding="utf-8",errors="ignore")
  except Exception:
    continue
  if not any(str(i) in raw for i in ids):
    continue
  try:
    data=json.loads(raw)
  except Exception:
    # jsonl
    for line in raw.splitlines():
      line=line.strip()
      if not line: continue
      try:
        o=json.loads(line)
      except Exception:
        continue
      bid=o.get("id") or o.get("bus_id") or (o.get("message") or {}).get("id")
      if bid in ids or str(bid) in {str(i) for i in ids}:
        found[int(bid) if str(bid).isdigit() else bid]=o
    continue
  # list or dict
  items=data if isinstance(data,list) else [data]
  if isinstance(data,dict):
    for k,v in data.items():
      if isinstance(v,list): items=v; break
      if isinstance(v,dict) and ("id" in v or "text" in v): items.append(v)
  for o in items:
    if not isinstance(o,dict): continue
    bid=o.get("id") or o.get("bus_id")
    if bid in ids:
      found[int(bid)]=o
print("found",sorted(found))
for bid in sorted(found):
  o=found[bid]
  text=o.get("text") or o.get("body") or o.get("message") or ""
  if isinstance(text,dict): text=text.get("text") or str(text)
  print("="*60, bid)
  print(str(text)[:2500])
