python3 <<'PY'
import json
from pathlib import Path
p=Path.home()/"Library/Application Support/youchu-agent-bus/state/youchu_ai_inbox.jsonl"
want={12450,12451,12452,12453,12454,12455,12456}
found={}
with p.open(encoding='utf-8',errors='ignore') as f:
  for line in f:
    if not any(str(i) in line for i in want):
      continue
    try:
      o=json.loads(line)
    except Exception:
      continue
    bid=o.get('id') or o.get('bus_id')
    if bid is None and 'message' in o:
      bid=(o.get('message') or {}).get('id')
    try:
      bid=int(bid)
    except Exception:
      continue
    if bid in want:
      found[bid]=o
print('found', sorted(found))
for bid in sorted(found):
  o=found[bid]
  text=o.get('text') or ''
  if not text and isinstance(o.get('payload'), dict):
    text=o['payload'].get('text') or o['payload'].get('body') or ''
  # nested
  for k in ('message','content','body'):
    if not text and isinstance(o.get(k), (str,dict)):
      v=o[k]
      text=v if isinstance(v,str) else (v.get('text') or v.get('body') or '')
  print('\n'+'='*20, bid, '='*20)
  print('keys', list(o.keys())[:20])
  print('from', o.get('from') or o.get('from_agent') or o.get('sender'))
  print('kind', o.get('kind') or o.get('type'))
  print(str(text)[:3000] if text else json.dumps(o, ensure_ascii=False)[:3000])
